window.PACK_DATA = window.PACK_DATA || {};
window.PACK_DATA["n4/grammar"] = [
  {id:"g-n4-potential",type:"grammar",source:"JLPT N4",level:"N4",title:"Potential form – can do",jp:"〜える／〜られる",summary:"The potential form says that someone is able to do something. う-verbs change the last sound to the え-row + る, る-verbs take られる; する becomes できる and くる becomes こられる. The object is usually marked with が.",structure:["う-verb: かく → かける","る-verb: たべる → たべられる","する → できる, くる → こられる"],examples:[{jp:"私[わたし]は漢字[かんじ]が読[よ]めます。",en:"I can read kanji."},{jp:"明日[あした]は早[はや]く来[こ]られますか。",en:"Can you come early tomorrow?"}],matches:[],tags:["verb-form","potential"]},
  {id:"g-n4-koto-ga-dekiru",type:"grammar",source:"JLPT N4",level:"N4",title:"ことができる – to be able to",jp:"〜ことができる",summary:"A slightly more formal way to say \"can\": dictionary form + ことができる. With a noun you use Noun + ができる.",structure:["Dictionary form + ことができる","Noun + ができる"],examples:[{jp:"ここで写真[しゃしん]を撮[と]ることができます。",en:"You can take photos here."},{jp:"兄[あに]はスキーができます。",en:"My older brother can ski."}],matches:[],tags:["potential"]},
  {id:"g-n4-passive",type:"grammar",source:"JLPT N4",level:"N4",title:"Passive form – to be done",jp:"〜れる／〜られる",summary:"The passive tells what happens to the subject; the doer is marked with に. It is often used when someone is bothered by what another person did. う-verbs: あ-row + れる, る-verbs: られる, する → される, くる → こられる.",structure:["う-verb: よむ → よまれる","る-verb: たべる → たべられる","Person に + passive verb"],examples:[{jp:"私[わたし]は先生[せんせい]にほめられました。",en:"I was praised by the teacher."},{jp:"弟[おとうと]にケーキを食[た]べられました。",en:"My younger brother ate my cake (and I am not happy about it)."}],matches:[],tags:["verb-form","passive"]},
  {id:"g-n4-causative",type:"grammar",source:"JLPT N4",level:"N4",title:"Causative form – to make / let someone do",jp:"〜せる／〜させる",summary:"The causative means that someone makes or lets another person do something. う-verbs: あ-row + せる, る-verbs: させる, する → させる, くる → こさせる. Causative て-form + ください asks for permission: \"please let me …\".",structure:["う-verb: いく → いかせる","る-verb: たべる → たべさせる","Causative て-form + ください"],examples:[{jp:"母[はは]は妹[いもうと]に野菜[やさい]を食[た]べさせます。",en:"My mother makes my younger sister eat vegetables."},{jp:"私[わたし]に払[はら]わせてください。",en:"Please let me pay."}],matches:[],tags:["verb-form","causative"]},
  {id:"g-n4-causative-passive",type:"grammar",source:"JLPT N4",level:"N4",title:"Causative-passive – to be made to do",jp:"〜させられる／〜される",summary:"The causative-passive says that someone is forced to do something they do not want to do. る-verbs: させられる; う-verbs usually take the short form あ-row + される (but はなす → はなさせられる).",structure:["う-verb: まつ → またされる","る-verb: たべる → たべさせられる","Person に + causative-passive verb"],examples:[{jp:"子[こ]どものとき、毎日[まいにち]ピアノを練習[れんしゅう]させられました。",en:"When I was a child, I was made to practice the piano every day."},{jp:"駅[えき]で一時間[いちじかん]も待[ま]たされました。",en:"I was kept waiting at the station for a whole hour."}],matches:[],tags:["verb-form","causative","passive"]},
  {id:"g-n4-volitional",type:"grammar",source:"JLPT N4",level:"N4",title:"Volitional form – let's, I'll",jp:"〜よう／〜おう",summary:"The plain form of 〜ましょう. It is used among friends for \"let's …\" and for your own decision \"I'll …\". う-verbs: お-row + う, る-verbs: よう, する → しよう, くる → こよう.",structure:["う-verb: いく → いこう","る-verb: たべる → たべよう","する → しよう, くる → こよう"],examples:[{jp:"一緒[いっしょ]に帰[かえ]ろう。",en:"Let's go home together."},{jp:"今日[きょう]は早[はや]く寝[ね]よう。",en:"I'll go to bed early today."}],matches:[],tags:["verb-form","volitional"]},
  {id:"g-n4-you-to-omou",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ようと思う – I think I will",jp:"〜ようとおもう",summary:"Volitional form + と思う tells what you intend to do. と思います is a decision made just now, と思っています a plan you have had for some time.",structure:["Volitional form + とおもう","Volitional form + とおもっている"],examples:[{jp:"来年[らいねん]、日本[にほん]に行[い]こうと思[おも]っています。",en:"I am thinking of going to Japan next year."}],matches:[],tags:["volitional","plan"]},
  {id:"g-n4-imperative",type:"grammar",source:"JLPT N4",level:"N4",title:"Imperative form – do it!",jp:"〜え／〜ろ",summary:"A strong, rough command. You hear it in emergencies, in sports, on signs and when quoting an order; in normal conversation it sounds rude. う-verbs: え-row, る-verbs: ろ, する → しろ, くる → こい.",structure:["う-verb: いく → いけ","る-verb: たべる → たべろ","する → しろ, くる → こい"],examples:[{jp:"早[はや]く逃[に]げろ！",en:"Run away, quick!"},{jp:"父[ちち]に「もっと勉強[べんきょう]しろ」と言[い]われました。",en:"My father told me to study more."}],matches:[],tags:["verb-form","command"]},
  {id:"g-n4-transitive-intransitive",type:"grammar",source:"JLPT N4",level:"N4",title:"Transitive and intransitive verbs",jp:"〜をあける／〜があく",summary:"Many verbs come in pairs. The transitive verb takes を and says that someone does something to an object; the intransitive verb takes が and says that something happens by itself.",structure:["Person が + object を + transitive verb","Thing が + intransitive verb"],examples:[{jp:"私[わたし]は窓[まど]を開[あ]けました。",en:"I opened the window."},{jp:"風[かぜ]で窓[まど]が開[あ]きました。",en:"The window opened because of the wind."}],matches:[],tags:["verb","transitivity"]},
  {id:"g-n4-ba",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ば – if",jp:"〜ば",summary:"The ば-form states a condition: if A is true, B follows. Verbs change the last sound to the え-row + ば, い-adjectives change い to ければ, and ない becomes なければ.",structure:["Verb: いく → いけば, たべる → たべれば","い-adjective: やすい → やすければ","Negative: いかない → いかなければ"],examples:[{jp:"春[はる]になれば、桜[さくら]が咲[さ]きます。",en:"When spring comes, the cherry trees bloom."},{jp:"安[やす]ければ買[か]います。",en:"If it is cheap, I will buy it."}],matches:[],tags:["conditional"]},
  {id:"g-n4-tara",type:"grammar",source:"JLPT N4",level:"N4",title:"〜たら – if, when, after",jp:"〜たら",summary:"Plain past form + ら. It means \"if\" or \"when/after\": B happens once A is completed. もし at the beginning makes it clear that it is an \"if\".",structure:["Verb: plain past + ら (いったら)","い-adjective: やすかったら","Noun／な-adjective + だったら"],examples:[{jp:"駅[えき]に着[つ]いたら、電話[でんわ]してください。",en:"Please call me when you arrive at the station."},{jp:"もし雨[あめ]が降[ふ]ったら、行[い]きません。",en:"If it rains, I won't go."}],matches:[],tags:["conditional"]},
  {id:"g-n4-tara-dou",type:"grammar",source:"JLPT N4",level:"N4",title:"〜たらどうですか – why don't you …?",jp:"〜たらどうですか",summary:"A suggestion or piece of advice: \"how about doing …?\". With a question word, 〜たらいいですか asks for advice: \"what should I do?\".",structure:["Plain past + ら + どうですか","Question word + plain past + ら + いいですか"],examples:[{jp:"少[すこ]し休[やす]んだらどうですか。",en:"Why don't you rest a little?"},{jp:"どこで切符[きっぷ]を買[か]ったらいいですか。",en:"Where should I buy the ticket?"}],matches:[],tags:["conditional","advice"]},
  {id:"g-n4-nara",type:"grammar",source:"JLPT N4",level:"N4",title:"〜なら – if it is the case that, as for",jp:"〜なら",summary:"なら takes up something the other person said or a situation (\"if that is so, then …\") and gives advice or an opinion about it. After a noun it also means \"as for …\".",structure:["Noun + なら","Plain form + (の)なら"],examples:[{jp:"京都[きょうと]に行[い]くなら、秋[あき]がいいですよ。",en:"If you are going to Kyoto, autumn is a good time."},{jp:"魚[さかな]なら食[た]べられます。",en:"Fish, I can eat."}],matches:[],tags:["conditional"]},
  {id:"g-n4-to-conditional",type:"grammar",source:"JLPT N4",level:"N4",title:"〜と – whenever, if (natural result)",jp:"〜と",summary:"Plain present form + と: whenever A happens, B always follows automatically. It is used for nature, machines, directions and habits; B cannot be a request or an intention.",structure:["Dictionary form／ない-form + と","Noun／な-adjective + だ + と"],examples:[{jp:"このボタンを押[お]すと、ドアが開[あ]きます。",en:"If you press this button, the door opens."},{jp:"右[みぎ]に曲[ま]がると、銀行[ぎんこう]があります。",en:"If you turn right, there is a bank."}],matches:[],tags:["conditional"]},
  {id:"g-n4-te-mo",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ても – even if, even though",jp:"〜ても",summary:"て-form + も: B is true even if A happens. With a question word (いくら, どんなに, なに) it means \"no matter how/what …\".",structure:["Verb て-form + も","い-adjective: 〜くても","Noun／な-adjective + でも"],examples:[{jp:"雨[あめ]が降[ふ]っても、出[で]かけます。",en:"Even if it rains, I will go out."},{jp:"いくら考[かんが]えても、わかりません。",en:"No matter how much I think about it, I don't understand."}],matches:[],tags:["conditional","concession"]},
  {id:"g-n4-noni-although",type:"grammar",source:"JLPT N4",level:"N4",title:"〜のに – although, even though",jp:"〜のに",summary:"のに connects two facts that do not fit together and shows surprise, disappointment or complaint. Nouns and な-adjectives take な before のに.",structure:["Plain form + のに","Noun／な-adjective + な + のに"],examples:[{jp:"薬[くすり]を飲[の]んだのに、熱[ねつ]が下[さ]がりません。",en:"Although I took medicine, my fever is not going down."},{jp:"日曜日[にちようび]なのに、仕事[しごと]があります。",en:"Even though it is Sunday, I have work."}],matches:[],tags:["concession"]},
  {id:"g-n4-noni-purpose",type:"grammar",source:"JLPT N4",level:"N4",title:"〜のに – for doing, in order to",jp:"〜のに",summary:"Dictionary form + のに tells what something is used for or needed for. It is followed by words like つかう, いい, べんりだ, ひつようだ or かかる.",structure:["Dictionary form + のに + つかう／べんりだ／かかる"],examples:[{jp:"このナイフは果物[くだもの]を切[き]るのに使[つか]います。",en:"This knife is used for cutting fruit."},{jp:"会社[かいしゃ]に行[い]くのに一時間[いちじかん]かかります。",en:"It takes an hour to get to the office."}],matches:[],tags:["purpose"]},
  {id:"g-n4-baai-wa",type:"grammar",source:"JLPT N4",level:"N4",title:"〜場合は – in case of, if",jp:"〜ばあいは",summary:"A rather formal \"in the case that …\", often found in rules and instructions.",structure:["Plain form + ばあいは","Noun + の + ばあいは","な-adjective + な + ばあいは"],examples:[{jp:"雨[あめ]の場合[ばあい]は、試合[しあい]は中止[ちゅうし]です。",en:"In case of rain, the match will be cancelled."},{jp:"遅[おく]れる場合[ばあい]は、連絡[れんらく]してください。",en:"If you are going to be late, please contact us."}],matches:[],tags:["conditional"]},
  {id:"g-n4-ba-yokatta",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ばよかった – I wish I had, I should have",jp:"〜ばよかった",summary:"ば-form + よかった expresses regret about something you did not do. The negative 〜なければよかった regrets something you did.",structure:["ば-form + よかった","ない-form: 〜なければ + よかった"],examples:[{jp:"もっと早[はや]く起[お]きればよかった。",en:"I should have got up earlier."},{jp:"あんなに食[た]べなければよかったです。",en:"I wish I had not eaten that much."}],matches:[],tags:["conditional","regret"]},
  {id:"g-n4-to-ii",type:"grammar",source:"JLPT N4",level:"N4",title:"〜といいですね – I hope",jp:"〜といい",summary:"Plain present form + といい expresses a hope. 〜といいですね is a wish for someone else, 〜といいんですが a wish for yourself.",structure:["Plain present form + といいですね","Plain present form + といいんですが"],examples:[{jp:"明日[あした]、晴[は]れるといいですね。",en:"I hope it will be sunny tomorrow."},{jp:"試験[しけん]に合格[ごうかく]できるといいんですが。",en:"I hope I can pass the exam."}],matches:[],tags:["wish"]},
  {id:"g-n4-te-miru",type:"grammar",source:"JLPT N4",level:"N4",title:"〜てみる – to try doing",jp:"〜てみる",summary:"て-form + みる means to do something to see what it is like.",structure:["て-form + みる"],examples:[{jp:"この靴[くつ]をはいてみてもいいですか。",en:"May I try these shoes on?"},{jp:"日本[にほん]の料理[りょうり]を作[つく]ってみました。",en:"I tried making Japanese food."}],matches:[],tags:["te-form"]},
  {id:"g-n4-te-oku",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ておく – to do in advance, to leave as it is",jp:"〜ておく",summary:"て-form + おく means to do something beforehand as preparation, or to leave something in its present state. In casual speech ておく becomes とく.",structure:["て-form + おく","Casual: 〜とく／〜どく"],examples:[{jp:"旅行[りょこう]の前[まえ]に、ホテルを予約[よやく]しておきます。",en:"I will book a hotel before the trip."},{jp:"窓[まど]は開[あ]けておいてください。",en:"Please leave the window open."}],matches:[],tags:["te-form"]},
  {id:"g-n4-te-shimau",type:"grammar",source:"JLPT N4",level:"N4",title:"〜てしまう／〜ちゃう – to finish; to do by mistake",jp:"〜てしまう／〜ちゃう",summary:"て-form + しまう means to do something completely, or that something happened that you regret. In casual speech てしまう becomes ちゃう and でしまう becomes じゃう.",structure:["て-form + しまう","Casual: 〜ちゃう／〜じゃう"],examples:[{jp:"宿題[しゅくだい]を全部[ぜんぶ]やってしまいました。",en:"I have finished all my homework."},{jp:"電車[でんしゃ]に傘[かさ]を忘[わす]れちゃった。",en:"I left my umbrella on the train (oh no)."}],matches:[],tags:["te-form","regret"]},
  {id:"g-n4-te-aru",type:"grammar",source:"JLPT N4",level:"N4",title:"〜てある – has been done (and is still so)",jp:"〜てある",summary:"て-form of a transitive verb + ある describes a state that is the result of someone doing something on purpose. The thing is marked with が.",structure:["Thing が + transitive verb て-form + ある"],examples:[{jp:"黒板[こくばん]に名前[なまえ]が書[か]いてあります。",en:"A name is written on the blackboard."},{jp:"飲[の]み物[もの]はもう買[か]ってあります。",en:"The drinks have already been bought."}],matches:[],tags:["te-form","state"]},
  {id:"g-n4-te-iku",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ていく – to do and go; to go on changing",jp:"〜ていく",summary:"て-form + いく means to do something and then go, or that a change or action continues from now on, away from the speaker.",structure:["て-form + いく"],examples:[{jp:"パーティーにワインを持[も]っていきます。",en:"I will take wine to the party."},{jp:"これから寒[さむ]くなっていきます。",en:"It will keep getting colder from now on."}],matches:[],tags:["te-form","direction"]},
  {id:"g-n4-te-kuru",type:"grammar",source:"JLPT N4",level:"N4",title:"〜てくる – to do and come back; to have become",jp:"〜てくる",summary:"て-form + くる means to do something and come (back), or that a change has been going on up to now, towards the speaker.",structure:["て-form + くる"],examples:[{jp:"ちょっとジュースを買[か]ってきます。",en:"I will just go and buy some juice (and come back)."},{jp:"日本語[にほんご]がおもしろくなってきました。",en:"Japanese has become interesting to me."}],matches:[],tags:["te-form","direction"]},
  {id:"g-n4-te-ageru",type:"grammar",source:"JLPT N4",level:"N4",title:"〜てあげる – to do something for someone",jp:"〜てあげる／〜てやる",summary:"て-form + あげる says that you (or someone) do a favour for another person. てやる is used towards younger family members, animals and plants.",structure:["Person に + て-form + あげる","て-form + やる (to someone below you)"],examples:[{jp:"友[とも]だちに傘[かさ]を貸[か]してあげました。",en:"I lent my friend an umbrella."},{jp:"毎朝[まいあさ]、犬[いぬ]を散歩[さんぽ]に連[つ]れていってやります。",en:"Every morning I take the dog for a walk."}],matches:[],tags:["te-form","giving"]},
  {id:"g-n4-te-kureru",type:"grammar",source:"JLPT N4",level:"N4",title:"〜てくれる – someone does something for me",jp:"〜てくれる",summary:"て-form + くれる says that someone does a favour for you or your family. The doer is the subject.",structure:["Person が + て-form + くれる"],examples:[{jp:"友[とも]だちが駅[えき]まで送[おく]ってくれました。",en:"My friend took me to the station."}],matches:[],tags:["te-form","giving"]},
  {id:"g-n4-te-morau",type:"grammar",source:"JLPT N4",level:"N4",title:"〜てもらう – to have someone do something",jp:"〜てもらう",summary:"て-form + もらう says that you receive a favour: you get someone to do something for you. The doer is marked with に.",structure:["Person に + て-form + もらう"],examples:[{jp:"先生[せんせい]に作文[さくぶん]を直[なお]してもらいました。",en:"I had my teacher correct my essay."}],matches:[],tags:["te-form","receiving"]},
  {id:"g-n4-te-hoshii",type:"grammar",source:"JLPT N4",level:"N4",title:"〜てほしい – I want you to",jp:"〜てほしい",summary:"て-form + ほしい says that you want another person to do something. That person is marked with に. \"I want you not to …\" is 〜ないでほしい.",structure:["Person に + て-form + ほしい","ない-form + で + ほしい"],examples:[{jp:"両親[りょうしん]に元気[げんき]でいてほしいです。",en:"I want my parents to stay healthy."},{jp:"ここでたばこを吸[す]わないでほしいです。",en:"I would like you not to smoke here."}],matches:[],tags:["te-form","wish"]},
  {id:"g-n4-te-itadakemasen-ka",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ていただけませんか – could you please",jp:"〜ていただけませんか",summary:"A very polite request, more polite than 〜てください and 〜てくれませんか.",structure:["て-form + いただけませんか"],examples:[{jp:"もう一度[いちど]説明[せつめい]していただけませんか。",en:"Could you please explain it once more?"}],matches:[],tags:["te-form","request","keigo"]},
  {id:"g-n4-te-sumimasen",type:"grammar",source:"JLPT N4",level:"N4",title:"〜てすみません – I am sorry for",jp:"〜てすみません",summary:"The て-form gives the reason for an apology. \"Sorry for not doing\" is 〜なくてすみません.",structure:["て-form + すみません","ない-form: 〜なくて + すみません"],examples:[{jp:"遅[おそ]くなってすみません。",en:"I am sorry for being late."}],matches:[],tags:["te-form","apology"]},
  {id:"g-n4-te-yokatta",type:"grammar",source:"JLPT N4",level:"N4",title:"〜てよかった – I am glad that",jp:"〜てよかった",summary:"て-form + よかった says that you are glad something happened or was done.",structure:["て-form + よかった","ない-form: 〜なくて + よかった"],examples:[{jp:"日本語[にほんご]を勉強[べんきょう]してよかったです。",en:"I am glad I studied Japanese."}],matches:[],tags:["te-form","feeling"]},
  {id:"g-n4-te-kurete-arigatou",type:"grammar",source:"JLPT N4",level:"N4",title:"〜てくれてありがとう – thank you for",jp:"〜てくれてありがとう",summary:"Thanks someone for what they did for you. To people above you, say 〜てくださってありがとうございます.",structure:["て-form + くれてありがとう","Polite: て-form + くださってありがとうございます"],examples:[{jp:"手伝[てつだ]ってくれてありがとう。",en:"Thank you for helping me."}],matches:[],tags:["te-form","thanks"]},
  {id:"g-n4-te-reason",type:"grammar",source:"JLPT N4",level:"N4",title:"〜て／〜で – and so, because",jp:"〜て／〜で",summary:"The て-form can give the reason or cause for what follows, typically a feeling or something you cannot control. Nouns and な-adjectives take で, the negative is 〜なくて.",structure:["Verb て-form／い-adjective 〜くて + result","Noun／な-adjective + で + result"],examples:[{jp:"ニュースを聞[き]いて、びっくりしました。",en:"I was surprised to hear the news."},{jp:"地震[じしん]で電車[でんしゃ]が止[と]まりました。",en:"The trains stopped because of the earthquake."}],matches:[],tags:["te-form","reason"]},
  {id:"g-n4-te-ita",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ていた – was doing",jp:"〜ていた",summary:"The past of 〜ている: an action that was in progress, or a state that continued, at some time in the past.",structure:["て-form + いた／いました"],examples:[{jp:"電話[でんわ]が鳴[な]ったとき、シャワーを浴[あ]びていました。",en:"When the phone rang, I was taking a shower."}],matches:[],tags:["te-form","past"]},
  {id:"g-n4-ru-tokoro",type:"grammar",source:"JLPT N4",level:"N4",title:"〜るところだ – to be about to do",jp:"〜るところだ",summary:"Dictionary form + ところだ says that you are just about to start doing something.",structure:["Dictionary form + ところだ"],examples:[{jp:"今[いま]から出[で]かけるところです。",en:"I am just about to go out."}],matches:[],tags:["tokoro","timing"]},
  {id:"g-n4-te-iru-tokoro",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ているところだ – to be in the middle of doing",jp:"〜ているところだ",summary:"ている + ところだ stresses that the action is going on right at this moment.",structure:["て-form + いる + ところだ"],examples:[{jp:"今[いま]、晩[ばん]ご飯[はん]を作[つく]っているところです。",en:"I am in the middle of making dinner right now."}],matches:[],tags:["tokoro","timing"]},
  {id:"g-n4-ta-tokoro",type:"grammar",source:"JLPT N4",level:"N4",title:"〜たところだ – to have just done",jp:"〜たところだ",summary:"Plain past form + ところだ says that something was finished only a moment ago.",structure:["Plain past form + ところだ"],examples:[{jp:"ちょうど今[いま]、家[いえ]に帰[かえ]ったところです。",en:"I have just got home this very moment."}],matches:[],tags:["tokoro","timing"]},
  {id:"g-n4-ta-bakari",type:"grammar",source:"JLPT N4",level:"N4",title:"〜たばかり – just did",jp:"〜たばかり",summary:"Plain past form + ばかり says that not much time has passed since something happened – in the speaker's feeling. It may be minutes or months ago.",structure:["Plain past form + ばかりだ","Plain past form + ばかりの + Noun"],examples:[{jp:"先月[せんげつ]日本[にほん]に来[き]たばかりです。",en:"I only came to Japan last month."},{jp:"さっき食[た]べたばかりなので、おなかがいっぱいです。",en:"I have just eaten, so I am full."}],matches:[],tags:["timing"]},
  {id:"g-n4-hajimeru",type:"grammar",source:"JLPT N4",level:"N4",title:"〜始める – to begin to",jp:"〜はじめる",summary:"Verb stem (ます-form without ます) + はじめる means to start doing something.",structure:["Verb stem + はじめる"],examples:[{jp:"去年[きょねん]からピアノを習[なら]い始[はじ]めました。",en:"I started learning the piano last year."}],matches:[],tags:["compound-verb"]},
  {id:"g-n4-owaru",type:"grammar",source:"JLPT N4",level:"N4",title:"〜終わる – to finish doing",jp:"〜おわる",summary:"Verb stem + おわる means to finish doing something.",structure:["Verb stem + おわる"],examples:[{jp:"その本[ほん]はもう読[よ]み終[お]わりました。",en:"I have already finished reading that book."}],matches:[],tags:["compound-verb"]},
  {id:"g-n4-tsuzukeru",type:"grammar",source:"JLPT N4",level:"N4",title:"〜続ける – to continue doing",jp:"〜つづける",summary:"Verb stem + つづける means to keep on doing something.",structure:["Verb stem + つづける"],examples:[{jp:"三時間[さんじかん]も歩[ある]き続[つづ]けました。",en:"We kept walking for three whole hours."}],matches:[],tags:["compound-verb"]},
  {id:"g-n4-dasu",type:"grammar",source:"JLPT N4",level:"N4",title:"〜出す – to suddenly start",jp:"〜だす",summary:"Verb stem + だす says that something starts suddenly and unexpectedly.",structure:["Verb stem + だす"],examples:[{jp:"急[きゅう]に雨[あめ]が降[ふ]り出[だ]しました。",en:"Suddenly it started to rain."},{jp:"赤[あか]ちゃんが泣[な]き出[だ]しました。",en:"The baby burst into tears."}],matches:[],tags:["compound-verb"]},
  {id:"g-n4-yasui",type:"grammar",source:"JLPT N4",level:"N4",title:"〜やすい – easy to do",jp:"〜やすい",summary:"Verb stem + やすい means that something is easy to do or happens easily. The result is an い-adjective.",structure:["Verb stem + やすい"],examples:[{jp:"このペンは書[か]きやすいです。",en:"This pen is easy to write with."}],matches:[],tags:["verb-stem","adjective"]},
  {id:"g-n4-nikui",type:"grammar",source:"JLPT N4",level:"N4",title:"〜にくい – hard to do",jp:"〜にくい",summary:"Verb stem + にくい means that something is difficult to do or does not happen easily. The result is an い-adjective.",structure:["Verb stem + にくい"],examples:[{jp:"この薬[くすり]は苦[にが]くて飲[の]みにくいです。",en:"This medicine is bitter and hard to take."}],matches:[],tags:["verb-stem","adjective"]},
  {id:"g-n4-zurai",type:"grammar",source:"JLPT N4",level:"N4",title:"〜づらい – hard to do (it feels uncomfortable)",jp:"〜づらい",summary:"Verb stem + づらい also means \"hard to do\", but the difficulty is felt by the speaker: it is physically or emotionally unpleasant.",structure:["Verb stem + づらい"],examples:[{jp:"この靴[くつ]は歩[ある]きづらいです。",en:"These shoes are hard to walk in."},{jp:"先生[せんせい]には言[い]いづらいことです。",en:"It is something that is hard to tell the teacher."}],matches:[],tags:["verb-stem","adjective"]},
  {id:"g-n4-nagara",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ながら – while doing",jp:"〜ながら",summary:"Verb stem + ながら: one person does two things at the same time. The main action comes last.",structure:["Verb stem + ながら + main action"],examples:[{jp:"音楽[おんがく]を聞[き]きながら勉強[べんきょう]します。",en:"I study while listening to music."}],matches:[],tags:["verb-stem","time"]},
  {id:"g-n4-nasai",type:"grammar",source:"JLPT N4",level:"N4",title:"〜なさい – do … (command)",jp:"〜なさい",summary:"Verb stem + なさい is a firm but not rude command, used by parents to children and teachers to pupils, and in test instructions.",structure:["Verb stem + なさい"],examples:[{jp:"早[はや]く起[お]きなさい。",en:"Get up quickly."},{jp:"野菜[やさい]も食[た]べなさい。",en:"Eat your vegetables, too."}],matches:[],tags:["verb-stem","command"]},
  {id:"g-n4-kata",type:"grammar",source:"JLPT N4",level:"N4",title:"〜方 – how to, way of doing",jp:"〜かた",summary:"Verb stem + かた makes a noun meaning \"the way of doing\". The object of the verb is linked with の.",structure:["Verb stem + かた","Noun の + verb stem + かた"],examples:[{jp:"この漢字[かんじ]の読[よ]み方[かた]を教[おし]えてください。",en:"Please tell me how to read this kanji."}],matches:[],tags:["verb-stem","noun"]},
  {id:"g-n4-tagaru",type:"grammar",source:"JLPT N4",level:"N4",title:"〜たがる – (someone else) wants to",jp:"〜たがる",summary:"〜たい is only for your own wishes. For another person, use verb stem + たがる, usually as 〜たがっている: he or she shows signs of wanting to.",structure:["Verb stem + たがる／たがっている"],examples:[{jp:"子[こ]どもは外[そと]で遊[あそ]びたがっています。",en:"The child wants to play outside."}],matches:[],tags:["verb-stem","wish"]},
  {id:"g-n4-garu",type:"grammar",source:"JLPT N4",level:"N4",title:"〜がる – (someone else) feels, shows signs of",jp:"〜がる／〜がっている",summary:"Adjectives of feeling (ほしい, こわい, さびしい …) describe only your own feelings. For another person, replace い with がる: he or she acts as if feeling so. The result is an う-verb that takes を.",structure:["い-adjective without い + がる","な-adjective + がる"],examples:[{jp:"妹[いもうと]は新[あたら]しいかばんをほしがっています。",en:"My younger sister wants a new bag."},{jp:"弟[おとうと]は犬[いぬ]をこわがります。",en:"My younger brother is afraid of dogs."}],matches:[],tags:["adjective","feeling"]},
  {id:"g-n4-sou-looks",type:"grammar",source:"JLPT N4",level:"N4",title:"〜そうだ – looks like, seems (from what I see)",jp:"〜そうだ",summary:"Verb stem or adjective stem + そうだ is your impression from how something looks: \"it looks …\", \"it is about to …\". いい becomes よさそう, ない becomes なさそう. Do not confuse it with plain form + そうだ (\"I heard\").",structure:["Verb stem + そうだ","い-adjective without い + そうだ","な-adjective + そうだ"],examples:[{jp:"このケーキはおいしそうです。",en:"This cake looks delicious."},{jp:"雨[あめ]が降[ふ]りそうです。",en:"It looks like it is going to rain."}],matches:[],tags:["appearance"]},
  {id:"g-n4-sou-ni",type:"grammar",source:"JLPT N4",level:"N4",title:"〜そうに／〜そうな – looking …, in a … way",jp:"〜そうに／〜そうな",summary:"The \"looks like\" そう behaves like a な-adjective: そうな comes before a noun, そうに before a verb.",structure:["Stem + そうな + Noun","Stem + そうに + Verb"],examples:[{jp:"子[こ]どもたちが楽[たの]しそうに遊[あそ]んでいます。",en:"The children are playing happily."},{jp:"高[たか]そうな時計[とけい]ですね。",en:"That is an expensive-looking watch."}],matches:[],tags:["appearance"]},
  {id:"g-n4-sou-da-hearsay",type:"grammar",source:"JLPT N4",level:"N4",title:"〜そうだ – I heard that",jp:"〜そうだ",summary:"Plain form + そうだ passes on information you heard or read. The source is given with 〜によると. Nouns and な-adjectives keep だ: 〜だそうだ.",structure:["Plain form + そうだ","Noun／な-adjective + だ + そうだ","Source + によると"],examples:[{jp:"天気予報[てんきよほう]によると、明日[あした]は雪[ゆき]が降[ふ]るそうです。",en:"According to the weather forecast, it will snow tomorrow."},{jp:"田中[たなか]さんは来月[らいげつ]結婚[けっこん]するそうです。",en:"I heard that Mr. Tanaka is getting married next month."}],matches:[],tags:["hearsay"]},
  {id:"g-n4-you-da",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ようだ – it seems that",jp:"〜ようだ",summary:"A judgement based on what you saw, heard or felt yourself: \"it seems that …\". It is more formal than みたいだ.",structure:["Plain form + ようだ","Noun + の + ようだ","な-adjective + な + ようだ"],examples:[{jp:"だれか来[き]たようです。",en:"It seems that someone has come."},{jp:"田中[たなか]さんは留守[るす]のようです。",en:"Mr. Tanaka seems to be out."}],matches:[],tags:["conjecture"]},
  {id:"g-n4-you-na",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ような／〜ように – like, as",jp:"〜ような／〜ように",summary:"Compares something with something similar or gives an example. ような comes before a noun, ように before a verb or adjective.",structure:["Noun + の + ような + Noun","Noun + の + ように + Verb／Adjective","Plain form + ように"],examples:[{jp:"彼[かれ]は子[こ]どものように笑[わら]います。",en:"He laughs like a child."},{jp:"東京[とうきょう]のような大[おお]きい町[まち]に住[す]みたいです。",en:"I want to live in a big city like Tokyo."}],matches:[],tags:["comparison"]},
  {id:"g-n4-mitai",type:"grammar",source:"JLPT N4",level:"N4",title:"〜みたいだ – looks like, seems (casual)",jp:"〜みたいだ",summary:"The casual version of ようだ: a guess from what you perceive, or a comparison \"is like …\". It follows the plain form directly, without だ, の or な.",structure:["Plain form + みたいだ","Noun／な-adjective + みたいだ"],examples:[{jp:"風邪[かぜ]をひいたみたいです。",en:"It seems I have caught a cold."},{jp:"あの雲[くも]は魚[さかな]みたいだ。",en:"That cloud looks like a fish."}],matches:[],tags:["conjecture","comparison"]},
  {id:"g-n4-mitai-ni",type:"grammar",source:"JLPT N4",level:"N4",title:"〜みたいな／〜みたいに – like (casual)",jp:"〜みたいな／〜みたいに",summary:"みたい behaves like a な-adjective: みたいな before a noun, みたいに before a verb or adjective. It is the casual version of のような／のように.",structure:["Noun + みたいな + Noun","Noun + みたいに + Verb／Adjective"],examples:[{jp:"今日[きょう]は夏[なつ]みたいに暑[あつ]いです。",en:"Today is as hot as summer."},{jp:"私[わたし]も姉[あね]みたいな人[ひと]になりたいです。",en:"I want to become a person like my older sister, too."}],matches:[],tags:["comparison"]},
  {id:"g-n4-rashii",type:"grammar",source:"JLPT N4",level:"N4",title:"〜らしい – apparently; typical of",jp:"〜らしい",summary:"Plain form + らしい is a guess based on what you heard or read: \"apparently …\". Noun + らしい can also mean \"just like a real …\", \"typical of …\". らしい itself is an い-adjective.",structure:["Plain form + らしい","Noun／な-adjective + らしい"],examples:[{jp:"あの店[みせ]のラーメンはおいしいらしいです。",en:"Apparently the ramen at that shop is good."},{jp:"今日[きょう]は春[はる]らしい天気[てんき]ですね。",en:"Today the weather is really spring-like."}],matches:[],tags:["conjecture","hearsay"]},
  {id:"g-n4-kamoshirenai",type:"grammar",source:"JLPT N4",level:"N4",title:"〜かもしれない – might, maybe",jp:"〜かもしれない",summary:"Plain form + かもしれない says that something is possible but you are not sure. Nouns and な-adjectives drop だ. The polite form is かもしれません, the casual short form かも.",structure:["Plain form + かもしれない","Noun／な-adjective + かもしれない"],examples:[{jp:"午後[ごご]は雨[あめ]が降[ふ]るかもしれません。",en:"It might rain in the afternoon."}],matches:[],tags:["conjecture"]},
  {id:"g-n4-hazu-da",type:"grammar",source:"JLPT N4",level:"N4",title:"〜はずだ – should be, I expect that",jp:"〜はずだ",summary:"はずだ says that you are fairly sure because you have a good reason: \"it should be so\".",structure:["Plain form + はずだ","Noun + の + はずだ","な-adjective + な + はずだ"],examples:[{jp:"荷物[にもつ]は明日[あした]届[とど]くはずです。",en:"The parcel should arrive tomorrow."},{jp:"今日[きょう]は日曜日[にちようび]だから、銀行[ぎんこう]は休[やす]みのはずです。",en:"Today is Sunday, so the bank should be closed."}],matches:[],tags:["conjecture","expectation"]},
  {id:"g-n4-hazu-ga-nai",type:"grammar",source:"JLPT N4",level:"N4",title:"〜はずがない – cannot be",jp:"〜はずがない",summary:"Says that you are sure something is impossible: \"there is no way that …\".",structure:["Plain form + はずがない","Noun + の + はずがない","な-adjective + な + はずがない"],examples:[{jp:"あの人[ひと]がそんなことを言[い]うはずがありません。",en:"That person would never say such a thing."}],matches:[],tags:["conjecture"]},
  {id:"g-n4-ni-mieru",type:"grammar",source:"JLPT N4",level:"N4",title:"〜に見える – to look, to appear",jp:"〜にみえる",summary:"Says how something looks to the eye. Nouns and な-adjectives take に, い-adjectives change い to く.",structure:["Noun／な-adjective + に + みえる","い-adjective: 〜く + みえる"],examples:[{jp:"あの雲[くも]は犬[いぬ]に見[み]えます。",en:"That cloud looks like a dog."},{jp:"母[はは]は年[とし]より若[わか]く見[み]えます。",en:"My mother looks younger than her age."}],matches:[],tags:["appearance"]},
  {id:"g-n4-ga-suru",type:"grammar",source:"JLPT N4",level:"N4",title:"〜がする – there is a smell, sound, taste, feeling",jp:"〜がする",summary:"A noun for something you sense (におい, おと, こえ, あじ, かんじ) + がする says that you notice it.",structure:["におい／おと／こえ／あじ + がする"],examples:[{jp:"台所[だいどころ]からいいにおいがします。",en:"There is a nice smell coming from the kitchen."},{jp:"外[そと]で変[へん]な音[おと]がしました。",en:"There was a strange sound outside."}],matches:[],tags:["senses"]},
  {id:"g-n4-to-kiita",type:"grammar",source:"JLPT N4",level:"N4",title:"〜と聞いた – I heard that",jp:"〜ときいた",summary:"Plain form + と聞きました reports something you heard. The person you heard it from is marked with から or に.",structure:["Plain form + ときいた","Person から／に + … + ときいた"],examples:[{jp:"友[とも]だちから、あの映画[えいが]はおもしろいと聞[き]きました。",en:"I heard from a friend that that movie is interesting."}],matches:[],tags:["hearsay","quotation"]},
  {id:"g-n4-to-iwarete-iru",type:"grammar",source:"JLPT N4",level:"N4",title:"〜と言われている – it is said that",jp:"〜といわれている",summary:"Gives a general opinion or common knowledge without naming who says it.",structure:["Plain form + といわれている"],examples:[{jp:"日本語[にほんご]は難[むずか]しいと言[い]われています。",en:"It is said that Japanese is difficult."}],matches:[],tags:["hearsay","passive"]},
  {id:"g-n4-to-itte-mo-ii",type:"grammar",source:"JLPT N4",level:"N4",title:"〜と言ってもいい – you could say that",jp:"〜といってもいい",summary:"Gives your judgement in a careful way: \"it would be fair to say that …\".",structure:["Plain form + といってもいい","Noun + (だ) + といってもいい"],examples:[{jp:"ここは日本[にほん]で一番[いちばん]きれいな町[まち]だと言[い]ってもいいです。",en:"You could say this is the most beautiful town in Japan."}],matches:[],tags:["opinion"]},
  {id:"g-n4-janai-ka",type:"grammar",source:"JLPT N4",level:"N4",title:"〜じゃないか – isn't it?, don't you think?",jp:"〜じゃないか／〜ではないか",summary:"Used when you expect the listener to agree, to express surprise, or to scold. Polite: じゃないですか; in writing: ではないか. Women tend to say じゃない.",structure:["Plain form + じゃないか","Noun／な-adjective + じゃないか"],examples:[{jp:"なかなかおいしいじゃないか。",en:"This is pretty good, isn't it?"},{jp:"危[あぶ]ないじゃないですか。",en:"That is dangerous, you know!"}],matches:[],tags:["sentence-ending"]},
  {id:"g-n4-kana",type:"grammar",source:"JLPT N4",level:"N4",title:"〜かな – I wonder",jp:"〜かな",summary:"A casual sentence ending for asking yourself a question or for a soft, indirect question.",structure:["Plain form + かな","Noun／な-adjective + かな"],examples:[{jp:"明日[あした]は晴[は]れるかな。",en:"I wonder if it will be sunny tomorrow."}],matches:[],tags:["sentence-ending","question"]},
  {id:"g-n4-kashira",type:"grammar",source:"JLPT N4",level:"N4",title:"〜かしら – I wonder (feminine)",jp:"〜かしら",summary:"Means the same as かな, but sounds feminine and a little old-fashioned.",structure:["Plain form + かしら","Noun／な-adjective + かしら"],examples:[{jp:"この服[ふく]、私[わたし]に似合[にあ]うかしら。",en:"I wonder if these clothes suit me."}],matches:[],tags:["sentence-ending","question"]},
  {id:"g-n4-kai",type:"grammar",source:"JLPT N4",level:"N4",title:"〜かい – casual yes/no question",jp:"〜かい",summary:"A soft, friendly question ending for yes/no questions, used mainly by older men towards younger people. With question words だい is used instead.",structure:["Plain form + かい","Noun／な-adjective + かい"],examples:[{jp:"元気[げんき]かい。",en:"Are you well?"},{jp:"もう宿題[しゅくだい]は終[お]わったかい。",en:"Have you finished your homework yet?"}],matches:[],tags:["sentence-ending","question"]},
  {id:"g-n4-you-ni",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ように – so that",jp:"〜ように",summary:"Gives the aim of an action when the aim is a state you cannot directly control: potential verbs, わかる, みえる, negative forms. (For actions you control, use ために.)",structure:["Dictionary form (potential) + ように","ない-form + ように"],examples:[{jp:"後[うし]ろの人[ひと]にも聞[き]こえるように、大[おお]きい声[こえ]で話[はな]します。",en:"I speak loudly so that the people at the back can hear, too."},{jp:"忘[わす]れないように、メモします。",en:"I take notes so that I don't forget."}],matches:[],tags:["purpose"]},
  {id:"g-n4-you-ni-suru",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ようにする – to make sure to, to try to",jp:"〜ようにする",summary:"Says that you make an effort to do (or not to do) something regularly. ようにしている is a habit you keep; ようにしてください is a soft request.",structure:["Dictionary form + ようにする","ない-form + ようにする"],examples:[{jp:"毎日[まいにち]野菜[やさい]を食[た]べるようにしています。",en:"I make sure to eat vegetables every day."},{jp:"授業[じゅぎょう]に遅[おく]れないようにしてください。",en:"Please make sure you are not late for class."}],matches:[],tags:["habit","effort"]},
  {id:"g-n4-you-ni-naru",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ようになる – to come to, to become able to",jp:"〜ようになる",summary:"Says that an ability or habit has changed over time: something you could not or did not do before, you now do. The opposite is 〜なくなる.",structure:["Dictionary form (often potential) + ようになる","ない-form: 〜なくなる"],examples:[{jp:"日本語[にほんご]の新聞[しんぶん]が読[よ]めるようになりました。",en:"I have become able to read Japanese newspapers."},{jp:"最近[さいきん]、早[はや]く起[お]きるようになりました。",en:"Recently I have started getting up early."}],matches:[],tags:["change"]},
  {id:"g-n4-koto-ni-suru",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ことにする – to decide to",jp:"〜ことにする",summary:"Says that you decide something yourself. ことにしている means you have made it your rule.",structure:["Dictionary form + ことにする","ない-form + ことにする"],examples:[{jp:"来月[らいげつ]から水泳[すいえい]を習[なら]うことにしました。",en:"I have decided to take swimming lessons from next month."},{jp:"夜[よる]はコーヒーを飲[の]まないことにしています。",en:"I make it a rule not to drink coffee at night."}],matches:[],tags:["decision"]},
  {id:"g-n4-koto-ni-naru",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ことになる – it has been decided that",jp:"〜ことになる",summary:"Says that something was decided by others or by circumstances, not by you alone. ことになっている describes a rule or arrangement.",structure:["Dictionary form + ことになる","ない-form + ことになる"],examples:[{jp:"来年[らいねん]、大阪[おおさか]で働[はたら]くことになりました。",en:"It has been decided that I will work in Osaka next year."},{jp:"ここでは靴[くつ]を脱[ぬ]ぐことになっています。",en:"You are supposed to take off your shoes here."}],matches:[],tags:["decision","rule"]},
  {id:"g-n4-yotei-da",type:"grammar",source:"JLPT N4",level:"N4",title:"〜予定だ – to be scheduled to, to plan to",jp:"〜よていだ",summary:"Tells about a fixed plan or schedule. It is more definite than つもりだ, which is only your intention.",structure:["Dictionary form + よていだ","Noun + の + よていだ"],examples:[{jp:"来週[らいしゅう]、出張[しゅっちょう]する予定[よてい]です。",en:"I am scheduled to go on a business trip next week."},{jp:"会議[かいぎ]は三時[さんじ]からの予定[よてい]です。",en:"The meeting is scheduled to start at three."}],matches:[],tags:["plan"]},
  {id:"g-n4-ku-suru",type:"grammar",source:"JLPT N4",level:"N4",title:"〜くする／〜にする – to make something …",jp:"〜くする／〜にする",summary:"Adjective + する means that someone changes something on purpose. (Compare 〜くなる／〜になる, where it changes by itself.)",structure:["い-adjective: 〜く + する","な-adjective／Noun + に + する"],examples:[{jp:"部屋[へや]を明[あか]るくしました。",en:"I made the room brighter."},{jp:"教室[きょうしつ]では静[しず]かにしてください。",en:"Please be quiet in the classroom."}],matches:[],tags:["adjective","change"]},
  {id:"g-n4-koto",type:"grammar",source:"JLPT N4",level:"N4",title:"こと – turning a verb into a noun",jp:"〜こと",summary:"Plain form + こと turns a clause into a noun phrase (\"doing …\", \"the fact that …\"). It is a little more formal than の and is the one used before です and in set patterns like ことができる.",structure:["Plain form + こと + は／が／を","Noun は + dictionary form + こと + です"],examples:[{jp:"私[わたし]の趣味[しゅみ]は写真[しゃしん]を撮[と]ることです。",en:"My hobby is taking photos."},{jp:"外国語[がいこくご]を習[なら]うことは楽[たの]しいです。",en:"Learning foreign languages is fun."}],matches:[],tags:["nominalizer"]},
  {id:"g-n4-to-iu-koto",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ということ – the fact that",jp:"〜ということ",summary:"Turns a whole statement into a noun: \"the fact that …\", \"that …\". It is used with verbs like しる, わかる, きく and わすれる. 〜ということだ at the end of a sentence means \"it means that …\" or \"I hear that …\".",structure:["Plain form + ということ"],examples:[{jp:"田中[たなか]さんが会社[かいしゃ]をやめたということを知[し]っていますか。",en:"Do you know that Mr. Tanaka quit the company?"}],matches:[],tags:["nominalizer","quotation"]},
  {id:"g-n4-to-iu",type:"grammar",source:"JLPT N4",level:"N4",title:"〜という／〜って – called, named",jp:"A という B",summary:"A という B introduces something the listener may not know: \"a B called A\". In casual speech という becomes って; って can also replace the quoting と (\"he said that …\").",structure:["Name + という + Noun","Casual: Name + って + Noun","Plain form + って (= と) + いう／きく"],examples:[{jp:"「さくら」という店[みせ]を知[し]っていますか。",en:"Do you know a shop called \"Sakura\"?"},{jp:"山田[やまだ]さんは今日[きょう]来[こ]ないって言[い]っていたよ。",en:"Yamada said he is not coming today."}],matches:[],tags:["quotation"]},
  {id:"g-n4-ka-dou-ka",type:"grammar",source:"JLPT N4",level:"N4",title:"〜かどうか／question word + か – whether; questions inside a sentence",jp:"〜かどうか／〜か",summary:"A question can be put inside a longer sentence. A yes/no question takes かどうか (\"whether or not\"); a question with a question word takes only か. Before か, だ is dropped.",structure:["Plain form + かどうか + しる／わかる／きく","Question word + plain form + か + しる／わかる／きく"],examples:[{jp:"明日[あした]行[い]けるかどうか、まだわかりません。",en:"I don't know yet whether I can go tomorrow."},{jp:"会議[かいぎ]が何時[なんじ]に始[はじ]まるか教[おし]えてください。",en:"Please tell me what time the meeting starts."}],matches:[],tags:["question","embedded-clause"]},
  {id:"g-n4-sa",type:"grammar",source:"JLPT N4",level:"N4",title:"〜さ – turning an adjective into a noun",jp:"〜さ",summary:"Replacing the final い of an い-adjective (or adding to a な-adjective) with さ makes a noun for a measurable quality: \"-ness\", \"how … something is\". いい becomes よさ.",structure:["い-adjective without い + さ","な-adjective + さ"],examples:[{jp:"この山[やま]の高[たか]さはどのくらいですか。",en:"How high is this mountain?"},{jp:"家族[かぞく]の大切[たいせつ]さがわかりました。",en:"I came to understand how important family is."}],matches:[],tags:["adjective","noun"]},
  {id:"g-n4-nakereba-naranai",type:"grammar",source:"JLPT N4",level:"N4",title:"〜なければならない／〜なければいけない – must, have to",jp:"〜なければならない／〜なければいけない",summary:"ない-form without い + ければならない means \"must\". ならない sounds like a general rule or duty, いけない is more personal; both are common. Casual speech shortens it to なきゃ.",structure:["ない-form: 〜なければ + ならない","ない-form: 〜なければ + いけない"],examples:[{jp:"明日[あした]までにレポートを出[だ]さなければなりません。",en:"I have to hand in the report by tomorrow."},{jp:"もう帰[かえ]らなければいけません。",en:"I have to go home now."}],matches:["g-g12-nakereba"],tags:["obligation"]},
  {id:"g-n4-nakute-mo-ii",type:"grammar",source:"JLPT N4",level:"N4",title:"〜なくてもいい – don't have to",jp:"〜なくてもいい",summary:"ない-form without い + くてもいい says that something is not necessary.",structure:["ない-form: 〜なくても + いい"],examples:[{jp:"明日[あした]は来[こ]なくてもいいです。",en:"You don't have to come tomorrow."}],matches:[],tags:["obligation","permission"]},
  {id:"g-n4-naide",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ないで – without doing; instead of doing",jp:"〜ないで",summary:"ない-form + で joins two actions: you do B without doing A, or you do B instead of A.",structure:["ない-form + で + main action"],examples:[{jp:"朝[あさ]ご飯[はん]を食[た]べないで学校[がっこう]に行[い]きました。",en:"I went to school without eating breakfast."},{jp:"バスに乗[の]らないで、歩[ある]いて帰[かえ]りましょう。",en:"Let's walk home instead of taking the bus."}],matches:[],tags:["negative","te-form"]},
  {id:"g-n4-ga-hitsuyou",type:"grammar",source:"JLPT N4",level:"N4",title:"〜が必要だ – to need",jp:"〜がひつようだ",summary:"ひつよう is a な-adjective meaning \"necessary\". The thing that is needed is marked with が, the person or purpose with に.",structure:["Noun + が + ひつようだ","Noun + に + Noun + が + ひつようだ","Dictionary form + のに + Noun + が + ひつようだ"],examples:[{jp:"外国[がいこく]に行[い]くのにパスポートが必要[ひつよう]です。",en:"You need a passport to go abroad."}],matches:[],tags:["necessity"]},
  {id:"g-n4-hitsuyou-ga-aru",type:"grammar",source:"JLPT N4",level:"N4",title:"〜必要がある – it is necessary to",jp:"〜ひつようがある",summary:"Dictionary form + 必要がある says that an action is necessary. The negative 〜必要はない means \"there is no need to\".",structure:["Dictionary form + ひつようがある","Dictionary form + ひつようはない"],examples:[{jp:"もう一度[いちど]調[しら]べる必要[ひつよう]があります。",en:"It is necessary to check once more."},{jp:"急[いそ]ぐ必要[ひつよう]はありません。",en:"There is no need to hurry."}],matches:[],tags:["necessity"]},
  {id:"g-n4-ga-hoshii",type:"grammar",source:"JLPT N4",level:"N4",title:"〜がほしい – to want (a thing)",jp:"〜がほしい",summary:"ほしい is an い-adjective for wanting a thing; the thing is marked with が. It is used for your own wishes (for other people: ほしがっている).",structure:["Noun + が + ほしい"],examples:[{jp:"新[あたら]しい自転車[じてんしゃ]がほしいです。",en:"I want a new bicycle."}],matches:[],tags:["wish"]},
  {id:"g-n4-o-ni-naru",type:"grammar",source:"JLPT N4",level:"N4",title:"お〜になる – honorific verb form",jp:"お〜になる",summary:"お + verb stem + になる raises the actions of a person you respect (a customer, a teacher, your boss). Never use it for your own actions. Verbs with a special honorific form (いらっしゃる, めしあがる …) use that instead.",structure:["お + verb stem + になる"],examples:[{jp:"先生[せんせい]はもうお帰[かえ]りになりました。",en:"The teacher has already gone home."}],matches:[],tags:["keigo","honorific"]},
  {id:"g-n4-o-kudasai",type:"grammar",source:"JLPT N4",level:"N4",title:"お〜ください – please do (honorific)",jp:"お〜ください",summary:"A respectful request, often heard in shops, stations and announcements. する-nouns take ご: ご〜ください.",structure:["お + verb stem + ください","ご + する-noun + ください"],examples:[{jp:"こちらで少々[しょうしょう]お待[ま]ちください。",en:"Please wait here a moment."},{jp:"ご注意[ちゅうい]ください。",en:"Please be careful."}],matches:[],tags:["keigo","request"]},
  {id:"g-n4-irassharu",type:"grammar",source:"JLPT N4",level:"N4",title:"いらっしゃる – to be, to go, to come (honorific)",jp:"いらっしゃる",summary:"The honorific verb for いる, いく and くる. Its ます-form is irregular: いらっしゃいます. 〜ていらっしゃる is the honorific of 〜ている.",structure:["いる／いく／くる → いらっしゃる","て-form + いらっしゃる"],examples:[{jp:"社長[しゃちょう]は今[いま]、会議室[かいぎしつ]にいらっしゃいます。",en:"The company president is in the meeting room now."},{jp:"明日[あした]は何時[なんじ]にいらっしゃいますか。",en:"What time will you come tomorrow?"}],matches:[],tags:["keigo","honorific"]},
  {id:"g-n4-nasaru",type:"grammar",source:"JLPT N4",level:"N4",title:"なさる – to do (honorific)",jp:"なさる",summary:"The honorific verb for する. Its ます-form is irregular: なさいます.",structure:["する → なさる","する-noun + なさる"],examples:[{jp:"先生[せんせい]は何[なに]を研究[けんきゅう]なさっていますか。",en:"What are you researching, professor?"},{jp:"お飲[の]み物[もの]は何[なに]になさいますか。",en:"What would you like to drink?"}],matches:[],tags:["keigo","honorific"]},
  {id:"g-n4-gozaimasu",type:"grammar",source:"JLPT N4",level:"N4",title:"ございます – there is, to have (very polite)",jp:"ございます",summary:"The very polite form of あります, used towards customers and in formal situations.",structure:["Noun + が／は + ございます"],examples:[{jp:"お手洗[てあら]いは二階[にかい]にございます。",en:"The restroom is on the second floor."}],matches:[],tags:["keigo","polite"]},
  {id:"g-n4-de-gozaimasu",type:"grammar",source:"JLPT N4",level:"N4",title:"でございます – to be (very polite)",jp:"〜でございます",summary:"The very polite form of です, used by staff towards customers and about yourself or your own side.",structure:["Noun + でございます"],examples:[{jp:"こちらが新[あたら]しい商品[しょうひん]でございます。",en:"This is our new product."}],matches:[],tags:["keigo","polite"]},
  {id:"g-n4-itasu",type:"grammar",source:"JLPT N4",level:"N4",title:"いたす – to do (humble)",jp:"いたす／いたします",summary:"The humble verb for する: you lower your own action to show respect. It is almost always used as いたします.",structure:["する → いたす","お + verb stem + いたします"],examples:[{jp:"よろしくお願[ねが]いいたします。",en:"Thank you in advance. / I am in your hands."},{jp:"後[あと]でお電話[でんわ]いたします。",en:"I will call you later."}],matches:[],tags:["keigo","humble"]},
  {id:"g-n4-o-suru",type:"grammar",source:"JLPT N4",level:"N4",title:"お〜する – humble verb form",jp:"お〜する",summary:"お + verb stem + する describes something you do for a person you respect. する-nouns take ご. Even more humble: お〜いたします.",structure:["お + verb stem + する","ご + する-noun + する"],examples:[{jp:"荷物[にもつ]をお持[も]ちしましょうか。",en:"Shall I carry your luggage?"},{jp:"駅[えき]までご案内[あんない]します。",en:"I will show you the way to the station."}],matches:[],tags:["keigo","humble"]},
  {id:"g-n4-shi",type:"grammar",source:"JLPT N4",level:"N4",title:"〜し – and what's more; giving reasons",jp:"〜し、〜し",summary:"し after the plain form lists several facts or reasons and implies that there are more.",structure:["Plain form + し、plain form + し、…"],examples:[{jp:"このアパートは駅[えき]に近[ちか]いし、家賃[やちん]も安[やす]いです。",en:"This apartment is close to the station, and the rent is cheap, too."},{jp:"雨[あめ]だし、疲[つか]れたし、今日[きょう]は出[で]かけません。",en:"It is raining and I am tired, so I am not going out today."}],matches:[],tags:["particle","reason","listing"]},
  {id:"g-n4-toka-toka",type:"grammar",source:"JLPT N4",level:"N4",title:"〜とか〜とか – things like … and …",jp:"〜とか〜とか",summary:"A casual way to give examples from a longer list. It can follow nouns and plain-form verbs.",structure:["Noun + とか + Noun + とか","Dictionary form + とか + dictionary form + とか"],examples:[{jp:"休[やす]みの日[ひ]は掃除[そうじ]とか洗濯[せんたく]とかをします。",en:"On my days off I do things like cleaning and laundry."}],matches:[],tags:["particle","listing"]},
  {id:"g-n4-nado",type:"grammar",source:"JLPT N4",level:"N4",title:"〜など – such as, and so on",jp:"〜など",summary:"など after a noun (often after a list with や) shows that these are only examples. It is more formal than とか.",structure:["Noun (や Noun) + など"],examples:[{jp:"かばんの中[なか]に本[ほん]やノートなどがあります。",en:"In my bag there are books, notebooks and so on."}],matches:[],tags:["particle","listing"]},
  {id:"g-n4-demo",type:"grammar",source:"JLPT N4",level:"N4",title:"〜でも – … or something",jp:"〜でも",summary:"でも after a noun makes a suggestion softer by giving just one example: \"… or something like that\". After a question word it means \"any\": なんでも (anything), いつでも (any time).",structure:["Noun + でも","Question word + でも"],examples:[{jp:"お茶[ちゃ]でも飲[の]みませんか。",en:"Shall we have some tea or something?"},{jp:"いつでも電話[でんわ]してください。",en:"Please call me any time."}],matches:[],tags:["particle"]},
  {id:"g-n4-shika-nai",type:"grammar",source:"JLPT N4",level:"N4",title:"〜しか〜ない – only, nothing but",jp:"〜しか〜ない",summary:"しか is always used with a negative verb and means \"only\" – with the feeling that it is less than expected or not enough. しか replaces が and を.",structure:["Noun／number + しか + negative verb"],examples:[{jp:"財布[さいふ]に百円[ひゃくえん]しかありません。",en:"I have only 100 yen in my wallet."},{jp:"昨日[きのう]は三時間[さんじかん]しか寝[ね]ませんでした。",en:"I slept only three hours last night."}],matches:[],tags:["particle","amount"]},
  {id:"g-n4-mo-amount",type:"grammar",source:"JLPT N4",level:"N4",title:"Number + も – as many as, as much as",jp:"Number + も",summary:"も after a number or amount shows that the speaker feels it is a lot. With a negative verb and \"one\" (ひとつも, いちども) it means \"not even one\".",structure:["Number + counter + も","ひとつ／いちど + も + negative verb"],examples:[{jp:"昨日[きのう]は十時間[じゅうじかん]も寝[ね]ました。",en:"I slept as much as ten hours yesterday."},{jp:"納豆[なっとう]は一度[いちど]も食[た]べたことがありません。",en:"I have never eaten natto, not even once."}],matches:[],tags:["particle","amount"]},
  {id:"g-n4-bakari",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ばかり – nothing but, always",jp:"〜ばかり",summary:"ばかり after a noun or て-form says that there is or someone does only that, and too much of it – usually a complaint.",structure:["Noun + ばかり","て-form + ばかり + いる"],examples:[{jp:"弟[おとうと]は肉[にく]ばかり食[た]べます。",en:"My younger brother eats nothing but meat."},{jp:"息子[むすこ]はゲームをしてばかりいます。",en:"My son does nothing but play video games."}],matches:[],tags:["particle"]},
  {id:"g-n4-dake-de",type:"grammar",source:"JLPT N4",level:"N4",title:"〜だけで – just by, with only",jp:"〜だけで",summary:"だけ (\"only\") + で: something is enough or happens with only this.",structure:["Dictionary form／plain past form + だけで","Noun + だけで"],examples:[{jp:"このボタンを押[お]すだけで、写真[しゃしん]が撮[と]れます。",en:"You can take a photo just by pressing this button."},{jp:"見[み]ているだけで楽[たの]しいです。",en:"It is fun just to watch."}],matches:[],tags:["particle"]},
  {id:"g-n4-kara-tsukuru",type:"grammar",source:"JLPT N4",level:"N4",title:"〜から作る／〜で作る – made from, made of",jp:"〜からつくる／〜でつくる",summary:"から marks a raw material that changes completely and can no longer be seen; で marks a material you can still recognise. The same goes for できる (\"to be made\").",structure:["Raw material + から + つくる／できる","Material + で + つくる／できる"],examples:[{jp:"ワインはぶどうから作[つく]られます。",en:"Wine is made from grapes."},{jp:"この机[つくえ]は木[き]でできています。",en:"This desk is made of wood."}],matches:[],tags:["particle","material"]},
  {id:"g-n4-ni-ki-ga-tsuku",type:"grammar",source:"JLPT N4",level:"N4",title:"〜に気がつく – to notice, to realize",jp:"〜にきがつく",summary:"Says that you become aware of something. A clause is turned into a noun with の or こと first.",structure:["Noun + に + きがつく","Plain form + の／こと + に + きがつく"],examples:[{jp:"家[いえ]を出[で]てから、忘[わす]れ物[もの]に気[き]がつきました。",en:"After leaving the house, I noticed I had forgotten something."},{jp:"財布[さいふ]がないことに気[き]がつきました。",en:"I realized that my wallet was gone."}],matches:[],tags:["expression"]},
  {id:"g-n4-toki",type:"grammar",source:"JLPT N4",level:"N4",title:"〜とき – when",jp:"〜とき",summary:"A clause + とき gives the time of the main action. The tense before とき is relative: dictionary form = the main action happens before that action is completed, past form = after it is completed.",structure:["Plain form + とき","Noun + の + とき","な-adjective + な + とき"],examples:[{jp:"日本[にほん]に行[い]くとき、かばんを買[か]いました。",en:"I bought a bag when I was going to Japan (before leaving)."},{jp:"子[こ]どものとき、よく川[かわ]で遊[あそ]びました。",en:"When I was a child, I often played in the river."}],matches:[],tags:["time"]},
  {id:"g-n4-aida-ni",type:"grammar",source:"JLPT N4",level:"N4",title:"〜間／〜間に – while, during",jp:"〜あいだ／〜あいだに",summary:"あいだ means \"during the whole time\": the main action continues all through it. あいだに means \"at some point within that time\": the main action happens once and is finished before the time ends.",structure:["て-form + いる + あいだ(に)","Noun + の + あいだ(に)"],examples:[{jp:"子[こ]どもが寝[ね]ている間[あいだ]に、買[か]い物[もの]に行[い]きました。",en:"I went shopping while the child was sleeping."},{jp:"夏休[なつやす]みの間[あいだ]、ずっと祖母[そぼ]の家[いえ]にいました。",en:"I stayed at my grandmother's house all through the summer holidays."}],matches:[],tags:["time"]},
  {id:"g-n4-ato-de",type:"grammar",source:"JLPT N4",level:"N4",title:"〜後で – after",jp:"〜あとで",summary:"Says that B happens after A. The verb before あとで is always in the plain past form, even when talking about the future.",structure:["Plain past form + あとで","Noun + の + あとで"],examples:[{jp:"ご飯[はん]を食[た]べた後[あと]で、薬[くすり]を飲[の]みます。",en:"I take the medicine after eating."},{jp:"授業[じゅぎょう]の後[あと]で、図書館[としょかん]に行[い]きます。",en:"After class I am going to the library."}],matches:[],tags:["time"]},
  {id:"g-n4-made-ni",type:"grammar",source:"JLPT N4",level:"N4",title:"〜までに – by (a deadline)",jp:"〜までに",summary:"までに gives a time limit: the action must be finished before that point. (まで alone means the action continues until then.)",structure:["Time + までに","Dictionary form + までに"],examples:[{jp:"金曜日[きんようび]までに宿題[しゅくだい]を出[だ]してください。",en:"Please hand in your homework by Friday."}],matches:[],tags:["particle","time"]},
  {id:"g-n4-goro",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ごろ – around (a point in time)",jp:"〜ごろ",summary:"ごろ after a point in time means \"at about\". For amounts and lengths of time use くらい／ぐらい instead.",structure:["Point in time + ごろ"],examples:[{jp:"毎晩[まいばん]十一時[じゅういちじ]ごろ寝[ね]ます。",en:"I go to bed at around eleven every night."}],matches:[],tags:["time"]},
  {id:"g-n4-oki-ni",type:"grammar",source:"JLPT N4",level:"N4",title:"〜おきに – every other, at intervals of",jp:"〜おきに",summary:"Number + counter + おきに says that something is repeated with that interval in between. Careful: いちにちおきに means \"every other day\".",structure:["Number + counter + おきに"],examples:[{jp:"バスは十分[じゅっぷん]おきに来[き]ます。",en:"The bus comes every ten minutes."},{jp:"一日[いちにち]おきにジムに行[い]きます。",en:"I go to the gym every other day."}],matches:[],tags:["time","frequency"]},
  {id:"g-n4-amari-nai",type:"grammar",source:"JLPT N4",level:"N4",title:"あまり〜ない – not very, not much",jp:"あまり〜ない",summary:"あまり with a negative verb or adjective means \"not very\" or \"not often\". In casual speech it becomes あんまり.",structure:["あまり + negative verb／adjective"],examples:[{jp:"この映画[えいが]はあまりおもしろくないです。",en:"This movie is not very interesting."},{jp:"私[わたし]はあまりテレビを見[み]ません。",en:"I don't watch much TV."}],matches:["g-g3-frequency"],tags:["adverb","negative"]},
  {id:"g-n4-zenzen",type:"grammar",source:"JLPT N4",level:"N4",title:"全然〜ない – not at all",jp:"ぜんぜん〜ない",summary:"ぜんぜん with a negative verb or adjective means \"not at all\".",structure:["ぜんぜん + negative verb／adjective"],examples:[{jp:"中国語[ちゅうごくご]は全然[ぜんぜん]わかりません。",en:"I don't understand Chinese at all."}],matches:["g-g3-frequency"],tags:["adverb","negative"]},
  {id:"g-n4-sonna-ni",type:"grammar",source:"JLPT N4",level:"N4",title:"そんなに – so much, that much",jp:"そんなに",summary:"Refers to a degree that was just mentioned or that you can see. With a negative it means \"not that …\".",structure:["そんなに + verb／adjective","そんなに + negative"],examples:[{jp:"そんなに食[た]べたら、おなかが痛[いた]くなりますよ。",en:"If you eat that much, you will get a stomachache."},{jp:"この店[みせ]はそんなに高[たか]くないです。",en:"This shop is not that expensive."}],matches:[],tags:["adverb"]},
  {id:"g-n4-sore-ni",type:"grammar",source:"JLPT N4",level:"N4",title:"それに – besides, moreover",jp:"それに",summary:"Starts a sentence that adds one more point of the same kind to what was just said.",structure:["Sentence A。それに、Sentence B。"],examples:[{jp:"この部屋[へや]は広[ひろ]いです。それに、駅[えき]からも近[ちか]いです。",en:"This room is spacious. Besides, it is close to the station."}],matches:[],tags:["conjunction"]},
  {id:"g-n4-sore-demo",type:"grammar",source:"JLPT N4",level:"N4",title:"それでも – but still, even so",jp:"それでも",summary:"Starts a sentence that is true in spite of what was just said.",structure:["Sentence A。それでも、Sentence B。"],examples:[{jp:"何度[なんど]も失敗[しっぱい]しました。それでも、あきらめませんでした。",en:"I failed many times. Even so, I did not give up."}],matches:[],tags:["conjunction"]},
];
